using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long limit;
    cin >> n >> limit;
    vector<long long> w(n);
    for (int i = 0; i < n; i++) cin >> w[i];

    sort(w.begin(), w.end());
    long long i = 0, j = n - 1, boats = 0;
    while (i <= j) {
        if (w[i] + w[j] <= limit) i++;
        j--;
        boats++;
    }
    cout << boats << "\n";

    return 0;
}

